        const b = s.bp; b.x = p.x; b.y = p.y; b.z = p.z; b.yaw = p.yaw; b.pitch = pl.pitch; b.lean = bkLeanFromWire(p.bank); b.wheel = pl.wheel; b.braking = pl.braking;
