  },

  /* Rời phòng / thoát chế độ: ẩn hết, quên tên và xe của mình */
  clear(): void {
    me = -1;
    for (let i = 0; i < slots.length; i++) { const s = slots[i]; if (s.name !== null) { drCars.remove(i); s.name = null; } dropBike(s); s.veh = 0; hide(s); }
