40	  const g = vhBuildTypeGeometry('bike').clone();
41	  const role = g.getAttribute('aRole') as THREE.BufferAttribute, col = g.getAttribute('color') as THREE.BufferAttribute;
42	  const T = M.temp, paint = new THREE.Color(T.paint), shirt = new THREE.Color(shirtColor ?? T.shirt), helmet = new THREE.Color(T.helmet);
43	  for (let i = 0; i < role.count; i++) {
44	    const r = role.getX(i), c = r === Role.Paint ? paint : r === Role.Accent ? shirt : r === Role.Helmet ? helmet : null;
45	    if (c) col.setXYZ(i, c.r, c.g, c.b);
46	  }
47	  g.deleteAttribute('aRole');
48	  g.computeBoundingBox();
49	  const bb = g.boundingBox!, len = bb.max.x - bb.min.x;
50	  g.scale(B.length / len, 1, 1);                                     // mặt cắt giữ nguyên, chỉ dài theo thân va chạm
