55	/* Tấm bóng mờ: elip mép mềm alpha = (1 − r²)^shadow.soft (xe máy hẹp; tấm vuông bo của ô tô thành mảng chữ nhật tối dưới xe máy).
56	   Cùng tham số vật liệu với drShadowShared của ô tô (chỉ khác ảnh) ⇒ cùng program; ô tô không đổi */
57	function bkShadowShared(): void {
58	  if (shadowMat) return;
59	  const n = 32, d = new Uint8Array(n * n * 4);
60	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
61	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
62	    const r2 = u * u + v * v, a = r2 >= 1 ? 0 : Math.pow(1 - r2, M.shadow.soft);
63	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
64	  }
65	  const tex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); tex.needsUpdate = true;
66	  tex.magFilter = tex.minFilter = THREE.LinearFilter;
67	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: tex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
68	  shadowMat.name = 'bikeShadow';
69	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
70	}
71	function bkTempMaterial(): THREE.MeshStandardMaterial {
