73	  return tempMat;
74	}
75	/* Vật liệu mặt đồng hồ: mỗi xe một bản, cùng tham số ⇒ cùng program. Có sẵn map (ảnh 1 × 1 trắng) để program đã làm nóng trùng với lúc
76	   dash.ts gắn texture canvas (đổi map cùng loại không biên dịch lại) */
77	let dashBlank: THREE.DataTexture | null = null;
78	function bkDashMaterial(): THREE.MeshBasicMaterial {
79	  if (!dashBlank) { dashBlank = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1, THREE.RGBAFormat); dashBlank.colorSpace = THREE.SRGBColorSpace; dashBlank.needsUpdate = true; }
80	  const m = new THREE.MeshBasicMaterial({ color: M.dashColor, map: dashBlank });
81	  m.name = 'bikeDash';
82	  return m;
83	}
