85	/* ===== Vật liệu đèn: phát sáng × max(uNight · night, uOn); `night` nằm trong chuỗi shader nên khóa program theo `key` ===== */
86	function bkLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, on: number): void {
87	  const uOn = { value: on };
88	  m.onBeforeCompile = (s) => {
89	    s.uniforms.uNight = shared.uNight;
90	    s.uniforms.uOn = uOn;
91	    s.fragmentShader = 'uniform float uNight;\nuniform float uOn;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
92	      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uOn );`);
93	  };
94	  m.customProgramCacheKey = () => key;
95	  m.userData.lampOn = on;
96	}
