98	export interface BkSource {
99	  scene: THREE.Object3D;                       // cảnh gốc (không thêm vào cảnh; chỉ để sao chép)
100	  axis: THREE.Vector3;                         // trục cổ lái (đơn vị) trong hệ nút cha của front, hướng lên
101	  tail: THREE.Material; tailBrake: THREE.Material;
102	  sigL: THREE.Material; sigLOn: THREE.Material; sigR: THREE.Material; sigROn: THREE.Material;
103	}
