129	/* ===== Nạp (nhớ đệm), làm nóng ===== */
130	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
131	export function bkModelSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
132	/* Vật thể khác của chế độ cần làm nóng cùng lượt (fx.ts: vệt pha, bụi nước): mỗi hàm trả một nhóm tạm, gỡ ra sau khi làm nóng */
133	const warmAlso: (() => THREE.Object3D)[] = [];
134	export function bkModelWarmAlso(fn: () => THREE.Object3D): void { if (!warmAlso.includes(fn)) warmAlso.push(fn); }
135	
136	/* Làm nóng mọi thứ xe dùng: cảnh nguồn (thân, cổ lái, bánh, đèn), mặt đồng hồ (MeshBasicMaterial), hình tạm, tấm bóng, cùng các nhóm của bkModelWarmAlso
137	   (vệt pha, bụi nước: khung đêm / mưa đầu tiên không giật). Bản đèn sáng / phanh cùng program với bản thường nên không cần. Gỡ cảnh nguồn ra (về không cha)
138	   sau khi làm nóng; chờ tối đa model.warmMs */
139	async function bkModelWarmAll(src: BkSource): Promise<void> {
140	  if (!warm) return;
141	  const g = new THREE.Group(), tg = bkTempGeometry(), dm = bkDashMaterial();
142	  g.add(new THREE.Mesh(tg, bkTempMaterial()));
143	  bkShadowShared(); g.add(new THREE.Mesh(shadowGeo!, shadowMat!));
144	  g.add(new THREE.Mesh(shadowGeo!, dm));
145	  g.add(src.scene);
146	  for (const f of warmAlso) g.add(f());
147	  let timer = 0;
148	  try { await Promise.race([warm(g), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
149	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
150	  finally { clearTimeout(timer); g.remove(src.scene); tg.dispose(); dm.dispose(); }
151	}
