153	async function bkModelDefaultLoader(): Promise<THREE.Object3D> {
154	  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
155	  const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + M.url);
