161	let late: Promise<BkSource | null> | null = null;   // nạp không giới hạn giờ: BkBike đổi sang mô hình thật cả khi xong sau timeoutMs
162	
163	/* Nạp mô hình xe máy. Không bao giờ ném / từ chối: lỗi hoặc quá model.timeoutMs → warn một lần, null.
164	   Quá giờ chỉ là câu trả lời của bkModelLoad: việc nạp vẫn chạy tiếp, xe đang có (BkBike) đổi sang mô hình thật khi nó xong (late) */
165	export function bkModelLoad(): Promise<BkSource | null> {
166	  if (cache) return cache;
167	  const work = (async () => {
168	    const src = bkModelSource(await loader());
169	    await bkModelWarmAll(src);
170	    return src;
171	  })();
172	  const LATE = {} as BkSource;   // dấu quá giờ
173	  let timer = 0;
174	  const p = Promise.race([work, new Promise<BkSource>((r) => { timer = setTimeout(() => r(LATE), M.timeoutMs) as unknown as number; })])
175	    .then((s) => { if (s !== LATE) return s; console.warn(`Lái xe máy: nạp mô hình xe quá ${M.timeoutMs} ms, dùng hình tạm`); return null; },
176	      (e) => { console.warn('Lái xe máy: không nạp được mô hình xe, dùng hình tạm', e); return null; })
177	    .finally(() => clearTimeout(timer));
178	  late = work.catch(() => null);   // lỗi đã báo ở nhánh race
179	  cache = p;
180	  return p;
181	}
