194	  private readonly roll = new THREE.Group();                         // nút cuộn lean quanh đường chạm đất
195	  anchors: BkAnchors;
196	  dashMat: THREE.MeshBasicMaterial | null = null;
197	  private temp: THREE.Mesh | null;
198	  private tempGeo: THREE.BufferGeometry | null;
199	  private disposed = false;
200	  private src: BkSource | null = null;
201	  private root: THREE.Object3D | null = null;                        // bản sao `scooter`: phần trên lò xo
202	  private front: THREE.Object3D | null = null;
203	  private wheelF: THREE.Object3D | null = null;
204	  private wheelR: THREE.Object3D | null = null;
205	  private readonly frontQ0 = new THREE.Quaternion(); private readonly wfQ0 = new THREE.Quaternion(); private readonly wrQ0 = new THREE.Quaternion();
206	  private readonly frontP0 = new THREE.Vector3(); private readonly wfP0 = new THREE.Vector3(); private readonly wrP0 = new THREE.Vector3();
207	  private readonly axisF = new THREE.Vector3();                      // trục cổ lái trong hệ cục bộ của front lúc nghỉ
208	  private tailMeshes: THREE.Mesh[] = []; private sigLMeshes: THREE.Mesh[] = []; private sigRMeshes: THREE.Mesh[] = [];
209	  private brakingNow = false; private sigLNow = false; private sigRNow = false;
210	  private readonly last: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
211	  private placed = false;
212	
213	  constructor(opts: BkBikeOpts = {}) {
214	    this.group.name = 'bike';
215	    this.group.add(this.roll);
216	    this.tempGeo = bkTempGeometry(opts.shirt);
217	    this.temp = new THREE.Mesh(this.tempGeo, bkTempMaterial());
218	    this.temp.name = 'bike-temp';
219	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
220	    this.roll.add(this.temp);
221	    bkShadowShared();
222	    const sh = new THREE.Mesh(shadowGeo!, shadowMat!);
223	    sh.scale.set(M.shadow.len, 1, M.shadow.wid);
224	    sh.position.y = M.shadow.lift;
225	    sh.layers.set(1); sh.castShadow = false; sh.receiveShadow = false; sh.renderOrder = 1;
226	    this.group.add(sh);
227	    const a = {} as BkAnchors;
228	    for (const [k, n] of ANCHORS) { const o = new THREE.Object3D(); o.name = 'bike-temp-' + n; this.roll.add(o); a[k] = o; }
