238	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
239	  private swap(src: BkSource): void {
240	    if (this.root || this.disposed) return;
241	    const root = src.scene.clone();
242	    this.src = src;
243	    this.front = root.getObjectByName('front')!; this.wheelF = root.getObjectByName('wheel_f')!; this.wheelR = root.getObjectByName('wheel_r')!;
244	    this.frontQ0.copy(this.front.quaternion); this.frontP0.copy(this.front.position);
245	    this.wfQ0.copy(this.wheelF.quaternion); this.wfP0.copy(this.wheelF.position);
246	    this.wrQ0.copy(this.wheelR.quaternion); this.wrP0.copy(this.wheelR.position);
247	    this.axisF.copy(src.axis).applyQuaternion(_q.copy(this.frontQ0).invert());
248	    this.dashMat = bkDashMaterial();
249	    root.traverse((o) => {
250	      const m = o as THREE.Mesh;
251	      if (!m.isMesh) return;
252	      const mat = m.material as THREE.Material;
253	      if (mat.name === 'dash') m.material = this.dashMat!;
254	      else if (mat === src.tail) this.tailMeshes.push(m);
255	      else if (mat === src.sigL) this.sigLMeshes.push(m);
