258	    for (const [k] of ANCHORS) this.anchors[k].removeFromParent();
259	    const a = {} as BkAnchors;
260	    for (const [k, n] of ANCHORS) a[k] = root.getObjectByName(n)!;
261	    this.anchors = a;
262	    this.root = root;
263	    this.roll.add(root);
264	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
