266	    if (this.placed) this.place(this.last);
267	  }
268	
269	  place(p: BkPlace): void {
270	    const l = this.last;
271	    if (p !== l) { l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.lean = p.lean; l.steer = p.steer; l.wheel = p.wheel; l.susF = p.susF; l.susR = p.susR; l.braking = p.braking; l.sig = p.sig; }
