273	    const g = this.group;
274	    g.position.set(p.x, p.y, p.z);
275	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(_q.setFromAxisAngle(AXZ, p.pitch));
276	    this.roll.rotation.x = -p.lean;                                  // lean > 0 nghiêng trái (−Z cục bộ)
277	    const root = this.root;
278	    if (!root) return;
