280	    /* cổ lái: xoay quanh trục (kẹp góc khóa lái); bánh trước trượt dọc trục theo susF */
281	    const st = p.steer > M.steerLock ? M.steerLock : p.steer < -M.steerLock ? -M.steerLock : p.steer === p.steer ? p.steer : 0;
282	    front.quaternion.setFromAxisAngle(this.src!.axis, st).multiply(this.frontQ0);
283	    wf.position.copy(this.axisF).multiplyScalar(p.susF).add(this.wfP0);
284	    wr.position.set(this.wrP0.x, this.wrP0.y + p.susR, this.wrP0.z);
285	    /* bánh lăn quanh Z cục bộ: xe tiến thì góc âm */
286	    wf.quaternion.copy(this.wfQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
287	    wr.quaternion.copy(this.wrQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
288	    /* phần trên lò xo: xoay φ quanh Z, dời ty sao cho hai tâm bánh về độ cao nghỉ của bánh sau (bánh chạm đất) */
289	    _v.copy(wf.position).applyQuaternion(front.quaternion).add(this.frontP0);   // tâm bánh trước trong hệ root
290	    const xf = _v.x, yf = _v.y, xr = wr.position.x, yr = wr.position.y;
291	    const phi = Math.atan2(yr - yf, xf - xr), sn = Math.sin(phi), cs = Math.cos(phi);
292	    root.rotation.set(0, 0, phi);
293	    root.position.set(0, this.wrP0.y - (xr * sn + yr * cs), 0);
294	    /* đèn: phanh, xi nhan (nửa chu kỳ đầu sáng) */
295	    if (p.braking !== this.brakingNow) {
296	      this.brakingNow = p.braking;
297	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
298	      for (const m of this.tailMeshes) m.material = mat;
299	    }
300	    const ph = shared.uTime.value * M.sigHz, blink = ph - Math.floor(ph) < 0.5;
301	    const onL = p.sig === 1 && blink, onR = p.sig === -1 && blink;
302	    if (onL !== this.sigLNow) { this.sigLNow = onL; const mat = onL ? this.src!.sigLOn : this.src!.sigL; for (const m of this.sigLMeshes) m.material = mat; }
303	    if (onR !== this.sigRNow) { this.sigRNow = onR; const mat = onR ? this.src!.sigROn : this.src!.sigR; for (const m of this.sigRMeshes) m.material = mat; }
304	  }
305	
306	  dispose(): void {
307	    if (this.disposed) return;
308	    this.disposed = true;
309	    this.group.removeFromParent();
310	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; }
311	    this.tempGeo?.dispose(); this.tempGeo = null;
312	    this.dashMat?.dispose(); this.dashMat = null;
313	    if (this.root) { this.roll.remove(this.root); this.root = null; }
314	    this.tailMeshes.length = 0; this.sigLMeshes.length = 0; this.sigRMeshes.length = 0;
315	  }
316	}
317	/* ============================ Lái xe máy: người lái có xương (src/explore/bike/rider.ts) ============================
318	   Spec D-040 §6, §17.10 (tư thế ngồi = bảng góc khớp trong code + IK, không chạy lại gen:people).
319	   - Nhân vật: nguồn của Đi dạo (stroll/rig.ts stRigLoad, p0 nam / p3 nữ theo stCharModel), một bản sao (src.clone = SkeletonUtils.clone), KHÔNG AnimationMixer:
320	     mỗi khung xương về tư thế đứng chữ A của mô hình (PlBones.restore) rồi cộng góc. Hệ C = hệ gốc bản sao: +X trước mặt, +Y lên, +Z bên phải (trùng hệ thân xe).
321	   - Cây nút: neo `seat` của xe (đọc lại bike.anchors mỗi khung: neo đổi khi hình tạm đổi sang mô hình thật) → group 'bike-rider' → bản sao nhân vật
322	     (dời để xương Pelvis ở rider.seat so với đỉnh yên). Nhờ vậy người theo đủ yaw / pitch / nghiêng / giảm xóc của phần trên lò xo.
323	   - Mỗi khung: 1) bảng góc khớp (bkRiderPose): lưng cúi chia ba đốt, cổ, đầu, gập hông, gập gối, đùi xoay ra, xương đòn; cộng lò xo phản ứng:
324	     lưng ngả theo gia tốc dọc, đầu bù (1 − headLean) độ nghiêng, đầu quay theo góc lái; 2) IK chân: plTwoBone hông → gối → cổ chân tới neo foot_l / foot_r
325	     (+ rider.ankle), đùi và cẳng chân xoay cung ngắn nhất từ tư thế bảng (giữ độ xoắn của bảng), bàn chân về hướng lúc đứng (phẳng trên sàn);
326	     3) IK tay: PlBones.ik của người treo dù với bộ số rider.arm / rider.finger, điểm nắm tới neo grip_l / grip_r (con của cổ lái: bẻ lái thì tay theo).
327	   - Mũ bảo hiểm nửa đầu: nửa khối cầu (SphereGeometry cắt nửa) gắn xương đầu, vật liệu MeshStandardMaterial màu theo đỉnh = cùng chương trình với hình tạm
328	     của xe (model.ts bkTempMaterial, đã làm nóng) nên không thêm program. Lớp 1, không bóng như xe.
329	   - Lệnh vẽ: nhân vật Rocketbox là 1 SkinnedMesh 3 primitive (thân, đầu, mảnh alpha) = 3 lệnh, như nhân vật đi dạo; mũ 1 lệnh.
330	   - Góc nhìn thứ nhất: xương đầu thu về scale ≈ 0 (mũ là con của xương đầu nên ẩn theo); thân, tay giữ.
331	   - Chưa có mô hình xe thật (bike.real = false): người ẩn, không tính IK (hình tạm của xe đã có người khối; hai người chồng nhau thì sai).
332	   Không cấp phát mỗi khung (D-018). */
333	import * as THREE from 'three';
334	import { CONFIG } from '../../config';
335	import { plTwoBone } from '../pilot/ik';
336	import { PlBones } from '../pilot/bones';
337	import { stRigLoad, type StRigSource } from '../stroll/rig';
338	import { stCharModel } from '../stroll/anim';
339	import type { BkBike } from './model';
340	
341	export interface BkRiderSig { lean: number; acc: number; susF: number; susR: number; steer: number }   // lean rad (trái +), acc m/s² gia tốc dọc, susF / susR m lún giảm xóc, steer rad (trái +)
342	
343	const RC = CONFIG.bike.rider;
344	const TAU = Math.PI * 2;
345	const A_REF = (50 / 3.6) / CONFIG.bike.perf.t50;   // m/s² — gia tốc khi vặn hết ga dưới 50 km/h (motion.ts A0)
346	
347	/* ===== Bảng góc khớp tư thế ngồi nền (rad), thứ tự cố định ===== */
348	export const BK_POSE = { spine: 0, neck: 1, head: 2, hip: 3, knee: 4, legSplit: 5, ankle: 6, clavicle: 7, clavicleFore: 8 } as const;
349	export const BK_POSE_N = 9;
350	export function bkRiderPose(out: Float32Array): void {
351	  const P = RC.pose;
352	  out[BK_POSE.spine] = P.spine; out[BK_POSE.neck] = P.neck; out[BK_POSE.head] = P.head;
353	  out[BK_POSE.hip] = P.hip; out[BK_POSE.knee] = P.knee; out[BK_POSE.legSplit] = P.legSplit; out[BK_POSE.ankle] = P.ankle;
354	  out[BK_POSE.clavicle] = P.clavicle; out[BK_POSE.clavicleFore] = P.clavicleFore;
355	}
356	
357	/* Nạp nhân vật ch (0 nam / 1 nữ) — chung bộ nạp, bộ đệm và làm nóng với Đi dạo. Không bao giờ từ chối: lỗi → null */
358	export function bkRiderLoad(ch: number): Promise<StRigSource | null> { return stRigLoad(stCharModel(ch)); }
359	
360	const AZ = new THREE.Vector3(0, 0, 1);
361	const _inv = new THREE.Matrix4(), _q = new THREE.Quaternion(), _q2 = new THREE.Quaternion(), _qa = new THREE.Quaternion(), _qb = new THREE.Quaternion(), _qc = new THREE.Quaternion();
362	const _h = new THREE.Vector3(), _k = new THREE.Vector3(), _a = new THREE.Vector3(), _d = new THREE.Vector3(), _d2 = new THREE.Vector3();
363	const _hip = [0, 0, 0], _tgt = [0, 0, 0], _pole = [0, 0, 0], _knee = [0, 0, 0], _end = [0, 0, 0];
364	const _tL = new THREE.Vector3(), _tR = new THREE.Vector3();
365	
366	/* Hình học mũ: nửa khối cầu (vỏ trên), màu theo đỉnh */
367	function bkHelmetGeometry(): THREE.BufferGeometry {
368	  const H = RC.helmet, g = new THREE.SphereGeometry(H.r, 20, 8, 0, TAU, 0, Math.PI / 2);
369	  const c = new THREE.Color(H.color), n = g.getAttribute('position').count, col = new Float32Array(n * 3);
370	  for (let i = 0; i < n; i++) { col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b; }
371	  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
372	  return g;
373	}
374	
375	export class BkRider {
376	  readonly group = new THREE.Group();
377	  readonly root: THREE.Object3D;
378	  readonly bones: PlBones;
379	  readonly helmet: THREE.Mesh;
380	  private readonly pose = new Float32Array(BK_POSE_N);
381	  private readonly feet: THREE.Object3D[];
382	  private readonly legL1 = [0, 0]; private readonly legL2 = [0, 0];   // m — đùi, cẳng chân
383	  private readonly footRest = [new THREE.Quaternion(), new THREE.Quaternion()];   // hướng bàn chân trong hệ C lúc đứng (phẳng)
384	  private readonly footT = [new THREE.Vector3(), new THREE.Vector3()];   // đích cổ chân, hệ C (cho debug)
385	  private readonly sx = new Float64Array(3); private readonly sv = new Float64Array(3);   // lò xo: lưng chúi, đầu bù nghiêng, đầu quay
386	  private disposed = false;
387	
388	  constructor(src: StRigSource) {
389	    this.group.name = 'bike-rider';
390	    this.root = src.clone(src.scene);
391	    this.root.name = 'bike-rider-body';
392	    this.group.add(this.root);
393	    const b = this.bones = new PlBones(this.root);   // thiếu xương thì ném (index.ts bắt)
394	    if (!b.foot[0] || !b.foot[1]) throw new Error('thiếu xương bàn chân');
395	    this.feet = [b.foot[0], b.foot[1]];
396	    /* số đo ở tư thế đứng: tay (PlBones.measure với bộ số của xe máy), chân, hướng bàn chân, chỗ xương hông */
397	    b.measure(RC.arm);
398	    b.updateMatrices();
399	    for (let i = 0; i < 2; i++) {
400	      b.pC(b.thigh[i], _h); b.pC(b.calf[i], _k); b.pC(this.feet[i], _a);
401	      this.legL1[i] = Math.max(0.05, _h.distanceTo(_k)); this.legL2[i] = Math.max(0.05, _k.distanceTo(_a));
402	      b.qC(this.feet[i], this.footRest[i]);
403	    }
404	    b.pC(b.pelvis, _h);
405	    this.root.position.set(RC.seat.fore - _h.x, RC.seat.up - _h.y, -_h.z);
406	    /* mũ: trục theo hệ C lúc đứng thẳng, tâm trên xương đầu; con của xương đầu */
407	    const H = RC.helmet;
408	    this.helmet = new THREE.Mesh(bkHelmetGeometry(), new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.45, metalness: 0.1 }));
409	    this.helmet.name = 'bike-helmet';
410	    b.qC(b.head, _q).invert();
411	    const hs = _h.setFromMatrixScale(_inv.copy(this.root.matrixWorld).invert().multiply(b.head.matrixWorld)).x || 1;   // tỉ lệ xương đầu so với hệ C (Rocketbox: Bip01 scale 0,01, đơn vị cm)
412	    this.helmet.quaternion.copy(_q).multiply(_qa.setFromAxisAngle(AZ, H.pitch));   // trục mũ = hệ C ngửa pitch quanh trục ngang
413	    this.helmet.position.set(H.fore, H.up, 0).applyQuaternion(_q).divideScalar(hs);
414	    this.helmet.scale.set(H.scale[0] / hs, H.scale[1] / hs, H.scale[2] / hs);
415	    b.head.add(this.helmet);
416	    this.group.traverse((o) => {
417	      o.layers.set(1);
418	      const m = o as THREE.Mesh;
419	      if (m.isMesh) { m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false; }
420	    });
421	    bkRiderPose(this.pose);
422	    this.group.visible = false;
423	  }
424	
425	  /* Lò xo bậc hai ba kênh tới đích, bước con ≤ 1/120 s (ổn định với mọi dt đã kẹp) */
426	  private spring(sig: BkRiderSig, d: number): void {
427	    const acc = Number.isFinite(sig.acc) ? sig.acc : 0, lean = Number.isFinite(sig.lean) ? sig.lean : 0, steer = Number.isFinite(sig.steer) ? sig.steer : 0;
428	    const t0 = acc >= 0 ? -RC.accLean * Math.min(1, acc / A_REF) : RC.brakeLean * Math.min(1, -acc / CONFIG.bike.perf.hardBrake);
429	    const t1 = lean * (1 - RC.headLean), t2 = steer * RC.steerLook;
430	    if (!(d > 0)) return;
431	    const w = TAU * RC.hz, z = RC.damp, n = Math.ceil(d * 120), h = d / n, x = this.sx, v = this.sv;
432	    for (let s = 0; s < n; s++) {
433	      v[0] += (w * w * (t0 - x[0]) - 2 * z * w * v[0]) * h; x[0] += v[0] * h;
434	      v[1] += (w * w * (t1 - x[1]) - 2 * z * w * v[1]) * h; x[1] += v[1] * h;
435	      v[2] += (w * w * (t2 - x[2]) - 2 * z * w * v[2]) * h; x[2] += v[2] * h;
436	    }
437	  }
438	
439	  /* Xoay xương o thêm R (hệ C) quanh khớp của nó (như PlBones.rotC) */
440	  private rotC(o: THREE.Object3D, R: THREE.Quaternion): void {
441	    this.bones.qC(o.parent, _q2);
442	    o.quaternion.premultiply(_q.copy(_q2).invert().multiply(R).multiply(_q2));
443	  }
444	
445	  /* Vị trí neo trong hệ C (ma trận thế giới đã cập nhật; _inv = nghịch đảo ma trận gốc bản sao) */
446	  private toC(o: THREE.Object3D, out: THREE.Vector3): THREE.Vector3 { return out.setFromMatrixPosition(o.matrixWorld).applyMatrix4(_inv); }
447	
448	  update(bike: BkBike, sig: BkRiderSig, dt: number): void {
449	    if (this.disposed) return;
450	    if (!bike.real) { this.group.visible = false; return; }
451	    const an = bike.anchors, b = this.bones, P = this.pose, B = BK_POSE;
452	    if (this.group.parent !== an.seat) an.seat.add(this.group);
453	    this.group.visible = true;
454	    const d = dt > 0 && Number.isFinite(dt) ? Math.min(dt, RC.dtMax) : 0;
455	    this.spring(sig, d);
456	    const x = this.sx;
457	    /* 1) bảng góc khớp + phản ứng (rotE: Euler YZX trong hệ C; quay âm quanh +Z = cúi trước; quay dương quanh +X = nghiêng phải; quay dương quanh +Y = quay trái) */
458	    b.restore();
459	    const k = 1 / b.spines.length;
460	    for (const s of b.spines) b.rotE(s, 0, 0, -(P[B.spine] + x[0]) * k);
461	    b.rotE(b.neck, 0, 0, -P[B.neck]);
462	    b.rotE(b.head, x[1], x[2], -P[B.head]);
463	    for (let i = 0; i < 2; i++) {
464	      const side = i ? 1 : -1;
465	      b.rotE(b.thigh[i], 0, -side * P[B.legSplit], P[B.hip]);
466	      b.rotE(b.calf[i], 0, 0, -P[B.knee]);
467	    }
468	    for (const a of b.arms) b.rotE(a.clav, -a.side * P[B.clavicle], 0, P[B.clavicleFore]);
469	    /* 2) chân */
470	    bike.group.updateMatrixWorld(true);
471	    b.updateMatrices();
472	    _inv.copy(this.root.matrixWorld).invert();
473	    const LP = RC.legPole, AK = RC.ankle;
474	    for (let i = 0; i < 2; i++) {
475	      const side = i ? 1 : -1, th = b.thigh[i], ca = b.calf[i], ft = this.feet[i], T = this.footT[i];
476	      this.toC(i ? an.footR : an.footL, T);
477	      T.x -= AK.back; T.y += AK.up;
478	      b.pC(th, _h); b.pC(ca, _k); b.pC(ft, _a);
479	      _hip[0] = _h.x; _hip[1] = _h.y; _hip[2] = _h.z;
480	      _tgt[0] = T.x; _tgt[1] = T.y; _tgt[2] = T.z;
481	      _pole[0] = _h.x + LP[0]; _pole[1] = _h.y + LP[1]; _pole[2] = _h.z + side * LP[2];
482	      plTwoBone(_hip, this.legL1[i], this.legL2[i], _tgt, _pole, _knee, _end);
483	      /* đùi: cung ngắn nhất từ hướng hiện tại (bảng) tới hướng hông → gối mới */
484	      _d.copy(_k).sub(_h).normalize(); _d2.set(_knee[0] - _h.x, _knee[1] - _h.y, _knee[2] - _h.z).normalize();
485	      _qa.setFromUnitVectors(_d, _d2);
486	      this.rotC(th, _qa);
487	      /* cẳng chân: hướng cũ (đã quay theo đùi) → gối → cổ chân mới */
488	      _d.copy(_a).sub(_k).normalize().applyQuaternion(_qa);
489	      _d2.set(_end[0] - _knee[0], _end[1] - _knee[1], _end[2] - _knee[2]).normalize();
490	      _qb.setFromUnitVectors(_d, _d2);
491	      this.rotC(ca, _qb);
492	      /* bàn chân: hướng lúc đứng (phẳng) + góc bảng quanh trục ngang */
493	      b.qC(ca, _q2).invert();
494	      ft.quaternion.copy(_q2).multiply(_qc.setFromAxisAngle(AZ, -P[B.ankle]).multiply(this.footRest[i]));
495	    }
496	    /* 3) tay */
497	    b.updateMatrices();
498	    this.toC(an.gripL, _tL); this.toC(an.gripR, _tR);
499	    b.ik(b.arms[0], _tL, RC.arm, RC.finger);
500	    b.ik(b.arms[1], _tR, RC.arm, RC.finger);
501	  }
502	
503	  /* Góc nhìn thứ nhất: thu xương đầu (và mũ) về ≈ 0 */
504	  setFirstPerson(on: boolean): void {
505	    this.bones.head.scale.setScalar(on ? 1e-4 : 1);
506	  }
507	
508	  /* Mắt trong hệ của nút frame (camera góc thứ nhất đo một lần ở tư thế ngồi nền: index.ts riderEye): điểm giữa hai xương mắt Bip01_LEye / REye
509	     (Rocketbox có), trả true; thiếu thì vị trí xương đầu, trả false (người gọi cộng cam1.headEye) */
510	  eyeLocal(frame: THREE.Object3D, out: THREE.Vector3): boolean {
511	    frame.updateWorldMatrix(true, true);
512	    const l = this.root.getObjectByName('Bip01_LEye') ?? this.root.getObjectByName('Bip01 LEye'), r = this.root.getObjectByName('Bip01_REye') ?? this.root.getObjectByName('Bip01 REye');
513	    if (l && r) out.setFromMatrixPosition(l.matrixWorld).add(_a.setFromMatrixPosition(r.matrixWorld)).multiplyScalar(0.5);
514	    else out.setFromMatrixPosition(this.bones.head.matrixWorld);
515	    frame.worldToLocal(out);
516	    return !!(l && r);
517	  }
518	
519	  /* m — khoảng cách điểm nắm – tay nắm (hai tay), cổ chân – đích cổ chân trên sàn (hai chân), sau update gần nhất */
520	  debug(): { handL: number; handR: number; footL: number; footR: number } {
521	    const b = this.bones;
522	    b.updateMatrices();
523	    _inv.copy(this.root.matrixWorld).invert();
524	    const f = (i: number): number => b.pC(this.feet[i], new THREE.Vector3()).distanceTo(this.footT[i]);
525	    return { handL: b.handErr(0), handR: b.handErr(1), footL: f(0), footR: f(1) };
526	  }
527	
528	  /* Gỡ khỏi xe, giải phóng skeleton riêng của bản sao, hình học / vật liệu mũ. Hình học / texture / vật liệu nhân vật thuộc nguồn dùng chung nên giữ */
529	  dispose(): void {
530	    if (this.disposed) return;
531	    this.disposed = true;
532	    this.group.removeFromParent();
533	    const seen = new Set<THREE.Skeleton>();
534	    this.root.traverse((o) => {
535	      const sk = (o as THREE.SkinnedMesh).isSkinnedMesh ? (o as THREE.SkinnedMesh).skeleton : null;
536	      if (sk && !seen.has(sk)) { seen.add(sk); sk.dispose(); }
537	    });
538	    this.helmet.geometry.dispose();
539	    (this.helmet.material as THREE.Material).dispose();
540	  }
541	}
542

