178	/* Âm thanh: điền BkSoundIn từ trạng thái xe (không cấp phát); bkSound tự giới hạn số lần ghi tham số (updateMs) */
179	function soundStep(s: BkState, nNear: number, tunnel: boolean, dry: boolean): void {
180	  _snd.v = s.v; _snd.rpm = s.rpm; _snd.throttle = s.throttle; _snd.brakeK = s.brakeK; _snd.sig = s.sig;
181	  _snd.sus = Math.max(Math.abs(s.susF), Math.abs(s.susR));
