209	/* Mắt góc thứ nhất theo người lái: đo một lần khi có người lái thật trên mô hình thật. Đặt xe về tư thế nghỉ (thẳng đứng, không lái, giảm xóc 0),
210	   người lái tư thế ngồi nền (lò xo phản ứng chưa chạy với người mới), giữa hai xương mắt (+ cam1.eyeFore; không có thì xương đầu + cam1.headEye)
211	   → hệ thân xe (nhóm ngoài: yaw · dốc, dốc = 0); rồi đặt lại như cũ */
212	function riderEye(): void {
213	  const s = state, r = rider, m = model;
214	  if (!r || !m || !m.real) { if (eyeFor) { eyeFor = null; bkCamSetEye(null); } return; }
215	  if (eyeFor === r || !s) return;
216	  eyeFor = r;
217	  _rest.x = s.x; _rest.y = s.y; _rest.z = s.z; _rest.yaw = s.yaw;
218	  m.place(_rest);
219	  r.update(m, _sig0, 0);
220	  r.setFirstPerson(false);
221	  const eyes = r.eyeLocal(m.group, _eye);
222	  bkCamSetEye(eyes ? { fore: _eye.x + C1.eyeFore, up: _eye.y } : { fore: _eye.x + C1.headEye.fore, up: _eye.y + C1.headEye.up });
223	  m.place(s);
224	  riderStep(s, 0);
225	}
