241	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
242	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
243	  if (!net || !model) return;
244	  const s = bkCreate(net, BK_SOLO_SLOT);
245	  let gy = -Infinity;
246	  for (const p of net.pads) {
247	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
248	    gy = Math.max(gy, p.y(x, z));
249	  }
250	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
251	  bkPitch(s, net);
252	  state = s;
253	  bkCamReset();
254	  model.place(s);
255	  riderStep(s, 0);
256	  riderEye();
257	  if (bkCamPlace(camera, s, camB, net, 0, true)) onResize();
258	  controls.target.set(s.x, s.y, s.z);
259	}
