286	  start(): void {
287	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
288	    const n = drEnsureNet();   // dựng net trước: lỗi ở đây thì thân va chạm vẫn là ô tô (mạng đường không phụ thuộc thân xe)
