302	    scene.add(bkFx.group); bkFx.start(n);
303	    bkRoadSet(true);                          // hạt nhựa + vệt ướt trên vật liệu đường (roadFx.ts; uRoadNear = 1 nếu CONFIG.bike.road.detail)
304	    riderNeed();
305	    riderStep(state, 0);
306	    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
307	    bkKeys.clear(); touch?.reset(); hornTouch = false;
308	    drHudShow(n); bkHudShow(); bkSound.start();
309	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
310	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
311	    riderEye();
312	    bkCamPlace(camera, state, camB, n, 0, true); onResize();   // fov / near góc thứ nhất; onResize cập nhật ma trận chiếu và hệ số cỡ điểm
313	    controls.target.set(state.x, state.y, state.z);
314	    document.body.classList.add('explore', 'drive', 'bike');
315	  },
316	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'bike' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng máy;
317	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
318	  startWatching(carry = false): void {
319	    const s = exMulti.session; if (!s) return;
320	    const n = drEnsureNet();
321	    net = n;
322	    if (state !== null) {   // vừa nhường chỗ: cất xe, người lái, hiệu ứng, tiếng của mình
323	      riderGen++; rider?.setFirstPerson(false);
324	      model?.group.removeFromParent(); bkFx.stop(); bkSound.stop(); bkHudHide();
325	    }
326	    state = null; watching = true; chased = carry;
327	    bkKeys.clear(); touch?.reset(); hornTouch = false;
328	    bkRoadSet(false);                         // hạt nhựa + vệt ướt chỉ khi tự lái
329	    exDrivers.setSelf(-1);
330	    driveView.far = CONFIG.drive.tunnelFar;
331	    drHudShow(n);
332	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
333	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
334	    camW.yaw = 0; camW.pitch = 0; camW.idle = 0;
335	    document.body.classList.add('explore', 'drive', 'bike', 'ex-watching');
336	    exMulti.onChange = bkOnMultiChange;
337	    exWatchShow(s);
338	  },
339	  update(dt: number): void {
340	    if (watching) { watchStep(dt); return; }
341	    if (!active()) return;
342	    bkInputFromKeys(bkKeys, _inp);
343	    bkTouchMerge(_inp, _dr, readTouch);   // gộp cảm ứng, không xóa phím (máy lai)
344	    bkSound.horn(bkKeys.has('KeyH') || hornTouch);
345	    const s = state!, tun = bkInTunnel(net!, s) && bkCovered(s), wd = weatherU.uWindDir.value;
346	    _inp.grip = bkGrip(weatherU.uWet.value, tun);                                       // mặt ướt (trễ theo mưa); đoạn hầm kín luôn khô
347	    _inp.steer += bkGustSteer(s.v, weatherU.uGust.value, wd[0], wd[1], s.yaw);        // gió giật đẩy nhẹ độ nghiêng (≤ fx.gust.steer)
348	    advance(dt, _inp);
349	  },
350	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
351	  afterRender(): void { /* chưa có việc */ },
352	  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
353	  stop(): void {
354	    if (state === null && !watching) return;
355	    state = null; bkKeys.clear(); touch?.reset(); hornTouch = false; riderGen++;
356	    document.getElementById('bkHorn')?.classList.remove('on');   // thoát khi đang giữ 📢: tắt sáng nút ngay, không chờ ngón nhả
357	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
358	    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent(); exDrivers.bikes.removeFromParent();   // xe người khác (ô tô, xe máy)
359	    bkSound.stop();
360	    bkHudHide();
361	    rider?.setFirstPerson(false);
362	    drHudHide();
363	    model?.group.removeFromParent();
364	    bkFx.stop();
365	    bkRoadSet(false);                         // uRoadNear = 0: vật liệu đường về đúng ảnh cũ
366	    driveView.far = 1;
367	    drUseBody(DR_CAR_BODY);
368	    document.body.classList.remove('drive', 'bike');
369	    if (saved) {
370	      if (!saved.explore) document.body.classList.remove('explore');
371	      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
372	      saved = null;
373	    }
374	    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
375	  },
376	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
377	  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
378	  placeAt: bkPlaceAt,
379	  /* Nạp mô hình thật (scooter.glb) và nhân vật người lái sớm, khi chọn thẻ Xe máy */
380	  preload(): void { void bkModelLoad(); void bkRiderLoad(stChar.get()); }
381	};
382	
383	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
384	export function setupBike(c: SwingController, onExit: () => void): void {
385	  ctrl = c; exit = onExit;
386	  window.addEventListener('keydown', (e) => {
387	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
388	    if (e.ctrlKey || e.metaKey || e.altKey) return;
389	    if (isField(e.target)) return;
390	    if (!BK_KEYS.has(e.code)) return;
391	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
392	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
393	    bkKeys.add(e.code);
394	    if (e.repeat) return;
395	    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
396	    if (e.code === 'KeyR') bkRecover(state!, net!);
397	    else if (e.code === 'KeyQ') bkSignal(state!, 1);
398	    else if (e.code === 'KeyE') bkSignal(state!, -1);
399	    else if (e.code === 'KeyV') bike.setView(camB.view === 3 ? 1 : 3);
400	  });
401	  window.addEventListener('keyup', (e) => {
402	    bkKeys.delete(e.code);
403	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
404	  });
405	  const drop = drBindDrop(window, document, bkKeys);
406	  const hornOff = () => { hornTouch = false; bkSound.horn(false); if (hornBtn) hornBtn.classList.remove('on'); };
407	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); hornOff(); } });
408	  window.addEventListener('blur', hornOff);
409	  document.addEventListener('visibilitychange', () => { if (document.hidden) hornOff(); });
410	  /* HUD riêng: xi nhan, góc nhìn, về làn bấm một lần (click: chuột, chạm, bàn phím); còi giữ (con trỏ riêng, nhả / hủy / mất capture là thôi) */
411	  const d = (id: string) => document.getElementById(id);
412	  const hornBtn = d('bkHorn');
413	  bkHudBind({ sigL: d('bkSigL'), sigR: d('bkSigR'), stuck: d('bkStuck'), reset: d('bkReset') });
414	  const onClick = (id: string, f: () => void) => d(id)?.addEventListener('click', () => { if (active()) { exMulti.activity(); f(); } });

file.content:
   - Nhiều người (Task 10, theo drive/index.ts): thẻ Xe máy mở phiên 'drive' veh 1 (5 chỗ chung với ô tô, chooser.ts). Có chỗ thì xuất phát theo slot, gửi vị trí + vận tốc
     + st = bkLeanToWire(độ nghiêng) sendHz lần/s (exMulti.updateDrive); xe người khác (ô tô / xe máy, multi/remoteDrive.ts) chỉ vẽ, nhãn, chấm trên bản đồ nhỏ, không va chạm.
     Xe của mình KHÔNG nằm trong drCars / exDrivers (vẽ ở model.ts). Hết chỗ: chế độ xem (startWatching) — camera sau xe được xem (cam3 của xe máy nếu xe đó là xe máy,
     drive.cam nếu ô tô), đồng hồ + bản đồ theo xe đó, không điều khiển; nhận lời mời thì start() (join đã mang veh 1). Rời máy: nhường chỗ sang xem; mất kết nối lúc xem:
     cờ 'lostBike' rồi thoát; máy chủ cũ không vọng veh (phiên về 'solo' / 'offline') lúc đang xem: lái một mình luôn.
   - Người lái: rider.ts, nhân vật theo stChar (chung Đi dạo), nạp ở preload() / start() (làm nóng qua stRigSetWarm của stroll/index.ts); chưa về thì xe không người,
     về sau stop() thì bỏ. Người gắn vào neo yên của xe nên rời cảnh cùng model.group.
   - Âm thanh (sound.ts bkSound): đề máy ở start(), tắt máy ở stop(); mỗi khung một BkSoundIn tái dùng (hộp xe gần dùng lại mảng trNearby của bkStep,
     river từ |x| so với mép kè, tunnel từ ô mặt đường dưới xe, mưa = 0 trong đoạn hầm kín); nút 🔊 #drSoundBtn chung với ô tô, bkSound.bind chỉ toggle khi đang lái xe máy.
   - Đêm + mưa (fx.ts, Task 7): grip = bkGrip(weatherU.uWet, xe trong đoạn hầm kín) mỗi khung; gió giật cộng bkGustSteer vào steer (BkInput giữ nguyên, chỉ khi v > vBlend);
     bkFx (vệt pha ban đêm, bụi nước khi mưa) vào cảnh ở start(), ra ở stop(), cập nhật sau model.place. "Hầm kín" = ô kiểu 'tunnel' và |x| ≤ HR.coverHalf:
     ô 'tunnel.tube' gồm cả hai dốc hở (|x| ≤ rampHalf), nơi mặt đường roadOut ướt khi mưa (han-tunnel/materials.ts registerWet).
   - Mặt đường nhìn gần (roadFx.ts, Task 8, mốc bỏ được): start() bkRoadSet(true) ⇒ shared.uRoadNear = 1 (nếu CONFIG.bike.road.detail), stop() về 0.
   - HUD riêng + cảm ứng (hudBike.ts, Task 9): đèn xi nhan #bkSigL / #bkSigR, nút 🎥 #bkView, 📢 #bkHorn (giữ), ↺ #bkReset, gợi ý #bkHint (thay #drHint), nhắc kẹt #bkStuck.
     Cảm ứng dùng nguyên drive/touch.ts trên #drHud (cần gạt, GA, PHANH, vuốt #drLook nhìn quanh) qua bộ chuyển bkTouchMerge, đọc SAU phím và gộp như ô tô.
     Kéo trên canvas nhận cả ngón tay chỉ khi không có giao diện cảm ứng (máy lai có chuột: #drLook ẩn); có thì #drLook lo, hai đường không giành nhau.
   Mỗi khung không cấp phát (D-018). */
import * as THREE from 'three';
import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
import { composer, onResize } from '../../core/postprocessing';
import { cam } from '../../views/state';
import { CONFIG } from '../../config';
import { driveView } from '../../environment/driveRoads';
import { drSetGate, type DrNet } from '../drive/net';
import { DR_GATE_SWING } from '../drive/roadData';
import { drUseBody, DR_CAR_BODY, type DrBox } from '../drive/collide';
import { drBindDrop } from '../drive/keys';
import { drHudShow, drHudHide, drHudUpdate } from '../drive/hud';
import { drCamPlace, type DrCam } from '../drive/camera';
import { drCars } from '../drive/cars';
import { exMulti } from '../multi';
import { exDrivers } from '../multi/remoteDrive';
import { bkLeanToWire } from '../multi/protocol';
import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
import { drTouchBind } from '../drive/touch';
import type { DrInput } from '../drive/motion';
import { drEnsureNet } from '../drive';
import { trNearby } from '../../common/trafficQuery';
import { exNightStep } from '../nightShows';
import { weatherU, shared } from '../../core/shared';
import { bkCreate, bkStep, bkRecover, bkSignal, bkPitch, BK_BODY, type BkState, type BkInput } from './motion';
import { bkInputFromKeys, BK_KEYS } from './keys';
import { BkBike, bkModelLoad, bkModelSetWarm, bkModelWarmAlso, type BkPlace } from './model';
import { BkRider, bkRiderLoad, type BkRiderSig } from './rider';
import { bkCamCreate, bkCamStep, bkCamPlace, bkCamDrag, bkCamSetEye, bkCamHideHead, type BkCam } from './camera';
import { BkDash } from './dash';
import { bkSound, bkRiverK, type BkSoundIn } from './sound';
import { bkFx, bkFxWarmObject, bkGrip, bkGustSteer } from './fx';
import { bkRoadSet } from './roadFx';
import { bkHudBind, bkHudShow, bkHudHide, bkHudUpdate, bkBlinkOn, bkStuckOn, bkTouchMerge } from './hudBike';
import { HR } from '../../bridges/han-tunnel/profile';
import { stChar } from '../stroll/char';
import type { SwingController } from '../../bridges/song-han/SwingController';

/* Làm nóng shader của xe máy (D-018), như drive/index.ts drCarSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
   đèn / sương / bóng lấy từ cảnh chính, camera chính. Nhóm làm nóng (mô hình, mặt đồng hồ, hình tạm, tấm bóng) do model.ts dựng, không thêm vào scene */
bkModelSetWarm(async (o: THREE.Object3D) => {
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(null);
  const a = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await a;
  renderer.setRenderTarget(composer.readBuffer);
  const b = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await b;
});
bkModelWarmAlso(bkFxWarmObject);   // vệt pha + bụi nước làm nóng cùng lượt với mô hình

const BK_SOLO_SLOT = -1;   // bkCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot (trên Cầu Rồng, đi Đông, bên phải)
const C1 = CONFIG.bike.cam1;

let net: DrNet | null = null;
let state: BkState | null = null;
let ctrl: SwingController | null = null;
let model: BkBike | null = null;   // hình xe của mình, dựng lần đầu vào chế độ
let rider: BkRider | null = null;  // người lái có xương (rider.ts); null khi nhân vật chưa nạp / nạp lỗi: xe không người (không hình tạm cho người)
let riderCh = -1;                  // nhân vật của rider hiện có (stChar)
let riderGen = 0;                  // tăng ở mỗi start() / stop(): kết quả nạp về muộn của lần trước bị bỏ
const _sig: BkRiderSig = { lean: 0, acc: 0, susF: 0, susR: 0, steer: 0 };   // tín hiệu người lái tái dùng mỗi khung
const bkKeys = new Set<string>();   // e.code đang giữ
const camB: BkCam = bkCamCreate();  // camera thứ nhất / thứ ba (camera.ts); view mặc định 1
let dash: BkDash | null = null;     // mặt đồng hồ canvas, dựng lần đầu vào chế độ
let motionK = C1.motion;            // hệ số chuyển động phụ: prefers-reduced-motion ⇒ motionReduced (đọc ở start())
let eyeFor: BkRider | null = null;  // người lái đã đo mắt góc thứ nhất (riderEye)
const _eye = new THREE.Vector3();
const _rest: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
const _sig0: BkRiderSig = { lean: 0, acc: 0, susF: 0, susR: 0, steer: 0 };
const _inp: BkInput = { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 };   // đầu vào tái dùng mỗi khung
const _dr: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };             // đầu vào cảm ứng tái dùng (bkTouchMerge)
let touch: ReturnType<typeof drTouchBind> | null = null;                      // cảm ứng trên #drHud (setupBike dựng)
const readTouch = (o: DrInput): void => { if (touch) touch.read(o); };
let hornTouch = false;                                                        // đang giữ nút 📢
const boxes: DrBox[] = [];          // hộp xe tự động gần xe, tái dùng mỗi khung
let saved: { fov: number; near: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại
const _snd: BkSoundIn = { v: 0, rpm: 0, throttle: 0, brakeK: 0, sus: 0, sig: 0, rain: 0, tunnel: false, river: 0, view: 1, near: boxes, nNear: 0, x: 0, z: 0, yaw: 0, t: 0 };   // đầu vào âm thanh tái dùng mỗi khung

let watching = false;               // đang xem xe người khác (hết chỗ lái hoặc vừa nhường chỗ): không có xe của mình, không đọc phím
let chased = false;                 // camera đã bám xe được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
let exit: () => void = () => {};    // thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem
const camW: DrCam = { yaw: 0, pitch: 0, idle: 0 };   // camera sau xe được xem (drCamPlace)
const _ws = { x: 0, z: 0, yaw: 0, v: 0 };            // xe đang xem đưa cho HUD (đồng hồ, bản đồ nhỏ), tái dùng mỗi khung

const active = () => cam.mode === 'bike' && state !== null;
const inMode = () => active() || watching;   // Esc và giao diện lái áp cho cả chế độ xem
const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');

/* Một bước: cổng nhịp quay, chuyển động (sơ tán nằm trong bkStep), hình xe, camera, HUD, hiệu ứng đêm */
function advance(dt: number, inp: BkInput): void {
  const s = state!, n = net!;
  if (ctrl) drSetGate(n, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  const nNear = trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes);
  bkStep(s, inp, n, boxes, nNear, dt);
  model!.place(s);
  const tunnel = bkInTunnel(n, s), dry = tunnel && bkCovered(s);
  bkFx.update(s, shared.uNight.value, dry ? 0 : weatherU.uRain.value, dt, s.pitch, dry ? 0 : weatherU.uWet.value);
  riderStep(s, dt);
  riderEye();
  bkCamStep(camB, s, dt, motionK);
  if (bkCamPlace(camera, s, camB, n, dt)) onResize();   // fov / near đổi trong lúc trộn góc nhìn
  rider?.setFirstPerson(bkCamHideHead(camB));   // cùng giá trị trộn đã làm mượt mà camera dùng
  if (dash) { dash.bind(model!.dashMat); dash.update(dt, s.v, s.rpm, s.sig); }
  controls.target.set(s.x, s.y, s.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
  const now = performance.now();
  exMulti.update(dt, now, null);                        // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
  exMulti.updateDrive(now, s, bkLeanToWire(s.lean));    // gửi vị trí + vận tốc + độ nghiêng (qua trường st) khi đang giữ chỗ
  drHudUpdate(s, exDrivers.dots());
  bkHudUpdate(s.sig, bkBlinkOn(shared.uTime.value), bkStuckOn(s.stuck));
  exNightStep(dt, false);
  soundStep(s, nNear, tunnel, dry);
}

/* Mỗi khung khi xem: xe người khác, nhãn, danh sách; camera sau xe được xem (bộ số cam3 của xe máy nếu xe đó là xe máy, drive.cam nếu ô tô), đồng hồ và bản đồ theo xe đó.
   Không có ai thì giữ nguyên */
function watchStep(dt: number): void {
  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  exMulti.update(dt, performance.now(), null);
  const w = exMulti.watchDriver(), ses = exMulti.session;
  if (w && ses) {
    const K = exDrivers.vehOf(ses.watched) === 1 ? CONFIG.bike.cam3 : CONFIG.drive.cam;
    drCamPlace(camera, w, camW, net!, dt, !chased, K); chased = true;
    if (camera.fov !== K.fov || camera.near !== CONFIG.bike.cam3.near) { camera.fov = K.fov; camera.near = CONFIG.bike.cam3.near; onResize(); }
    controls.target.set(w.x, w.y, w.z);
    _ws.x = w.x; _ws.z = w.z; _ws.yaw = w.yaw; _ws.v = w.v;
    drHudUpdate(_ws, exDrivers.dots(w));
  }
  exNightStep(dt, false);
}

/* Đổi phiên khi đang xem hoặc đang lái: vào lái, mất kết nối, bị thu hồi chỗ (như drOnMultiChange của ô tô) */
function bkOnMultiChange(): void {
  const s = exMulti.session; if (!s) return;
  if (watching) {
    if (s.phase === 'flying') { bike.start(); return; }   // chấp nhận lời mời: xuất phát như vào lái thường (join mang veh 1)
    if (s.phase === 'solo' && s.notice === 'offline') { bike.start(); return; }   // máy chủ cũ không vọng veh khi nhận lời mời: phiên đã trả chỗ, lái một mình
    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostBike'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện bkLostChooser
    exWatchRender();
  } else if (active()) {
    if (s.phase === 'watching') { bike.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'bkLost');   // vẫn lái, người khác đã biến mất
  }
}

/* Âm thanh: điền BkSoundIn từ trạng thái xe (không cấp phát); bkSound tự giới hạn số lần ghi tham số (updateMs) */
function soundStep(s: BkState, nNear: number, tunnel: boolean, dry: boolean): void {
  _snd.v = s.v; _snd.rpm = s.rpm; _snd.throttle = s.throttle; _snd.brakeK = s.brakeK; _snd.sig = s.sig;
  _snd.sus = Math.max(Math.abs(s.susF), Math.abs(s.susR));
  _snd.rain = dry ? 0 : weatherU.uRain.value; _snd.tunnel = tunnel; _snd.river = bkRiverK(s.x);
  _snd.view = camB.view; _snd.nNear = nNear; _snd.x = s.x; _snd.z = s.z; _snd.yaw = s.yaw; _snd.t = shared.uTime.value;
  bkSound.update(_snd);
}

/* Xe đang ở ô hầm không: ô chứa (x, z) có cao độ gần y nhất trong ± stepMax (như drive/net.ts drPadAt), kiểu 'tunnel'. Duyệt tuyến tính, không cấp phát */
function bkInTunnel(n: DrNet, s: BkState): boolean {
  const step = CONFIG.drive.stepMax;
  let best = -1, bestD = Infinity;
  for (let i = 0; i < n.pads.length; i++) {
    const p = n.pads[i];
    if (s.x < p.x0 || s.x > p.x1 || s.z < p.z0 || s.z > p.z1 || (p.gate !== undefined && n.closed.has(p.gate))) continue;
    const d = Math.abs(p.y(s.x, s.z) - s.y);
    if (d <= step && d < bestD) { best = i; bestD = d; }
  }
  return best >= 0 && n.pads[best].kind === 'tunnel';
}
/* Trong ô hầm thì đã ở đoạn có mái chưa (ngoài |x| > coverHalf là dốc hở: mưa, mặt ướt) */
const bkCovered = (s: BkState): boolean => Math.abs(s.x) <= HR.coverHalf;

/* Người lái theo xe (sau model.place): tín hiệu từ trạng thái chuyển động */
function riderStep(s: BkState, dt: number): void {
  if (!rider || !model) return;
  _sig.lean = s.lean; _sig.acc = s.acc; _sig.susF = s.susF; _sig.susR = s.susR; _sig.steer = s.steer;
  rider.update(model, _sig, dt);
}

/* Mắt góc thứ nhất theo người lái: đo một lần khi có người lái thật trên mô hình thật. Đặt xe về tư thế nghỉ (thẳng đứng, không lái, giảm xóc 0),
   người lái tư thế ngồi nền (lò xo phản ứng chưa chạy với người mới), giữa hai xương mắt (+ cam1.eyeFore; không có thì xương đầu + cam1.headEye)
   → hệ thân xe (nhóm ngoài: yaw · dốc, dốc = 0); rồi đặt lại như cũ */
function riderEye(): void {
  const s = state, r = rider, m = model;
  if (!r || !m || !m.real) { if (eyeFor) { eyeFor = null; bkCamSetEye(null); } return; }
  if (eyeFor === r || !s) return;
  eyeFor = r;
  _rest.x = s.x; _rest.y = s.y; _rest.z = s.z; _rest.yaw = s.yaw;
  m.place(_rest);
  r.update(m, _sig0, 0);
  r.setFirstPerson(false);
  const eyes = r.eyeLocal(m.group, _eye);
  bkCamSetEye(eyes ? { fore: _eye.x + C1.eyeFore, up: _eye.y } : { fore: _eye.x + C1.headEye.fore, up: _eye.y + C1.headEye.up });
  m.place(s);
  riderStep(s, 0);
}

/* Nạp người lái theo nhân vật đã chọn (stChar, chung với Đi dạo). Về sau stop() / start() khác thì bỏ; nhân vật đổi thì thay người cũ */
function riderNeed(): void {
  const ch = stChar.get(), gen = ++riderGen;
  if (rider && riderCh === ch) return;
  void bkRiderLoad(ch).then((src) => {
    if (gen !== riderGen || state === null || !src) return;
    try {
      const r = new BkRider(src);
      rider?.dispose(); rider = r; riderCh = ch;
      riderStep(state, 0);
    } catch (e) { console.warn('Lái xe máy: không dựng được người lái', e); }
  });
}

/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
  if (!net || !model) return;
  const s = bkCreate(net, BK_SOLO_SLOT);
  let gy = -Infinity;
  for (const p of net.pads) {
    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
    gy = Math.max(gy, p.y(x, z));
  }
  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
  bkPitch(s, net);
  state = s;
  bkCamReset();
  model.place(s);
  riderStep(s, 0);
  riderEye();
  if (bkCamPlace(camera, s, camB, net, 0, true)) onResize();
  controls.target.set(s.x, s.y, s.z);
}

/* Trạng thái camera về đầu (giữ góc nhìn đang chọn, trộn xong ngay) */
function bkCamReset(): void {
  const v = camB.view;
  Object.assign(camB, bkCamCreate());
  camB.view = v; camB.mix = v === 3 ? 1 : 0;
}

export const bike = {
  active,
  inMode,
  get state(): BkState | null { return state; },
  get net(): DrNet | null { return net; },
  get model(): BkBike | null { return model; },   // hình xe của mình (test: real, anchors)
  get rider(): BkRider | null { return rider; },  // người lái (test: debug(), setFirstPerson)
  get view(): 1 | 3 { return camB.view; },
  get cam(): BkCam { return camB; },               // test: mix, roll, bob, surge, yaw / pitch nhìn quanh
  get dash(): BkDash | null { return dash; },
  get cfg(): typeof CONFIG.bike { return CONFIG.bike; },   // test / kiểm tay: chỉnh số camera lúc chạy
  get sound(): typeof bkSound { return bkSound; },        // test: nodes(), on, graph
  get fx(): typeof bkFx { return bkFx; },                 // test: drawn() (vệt pha, số hạt bụi nước), group
  get input(): Readonly<BkInput> { return _inp; },        // test: đầu vào của khung gần nhất (grip theo mặt ướt / hầm kín)
  /* Đổi góc nhìn: trộn vị trí + hướng + fov + near trong cam1.mixS, không dừng xe */
  setView(v: 1 | 3): void { camB.view = v === 3 ? 3 : 1; },
  get watching(): boolean { return watching; },
  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot) */
  start(): void {
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    const n = drEnsureNet();   // dựng net trước: lỗi ở đây thì thân va chạm vẫn là ô tô (mạng đường không phụ thuộc thân xe)
    drUseBody(BK_BODY);
    net = n;
    const ses = exMulti.session;
    const slot = ses && ses.kind === 'drive' && ses.mySlot >= 0 ? ses.mySlot : BK_SOLO_SLOT;
    if (ses) exMulti.onChange = bkOnMultiChange;
    exDrivers.setSelf(-1);    // xe của mình không nằm trong drCars (model.ts vẽ)
    state = bkCreate(n, slot);
    camB.view = 1; bkCamReset();
    motionK = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches ? C1.motionReduced : C1.motion;
    if (!model) model = new BkBike();
    if (!dash) dash = new BkDash();
    scene.add(model.group);
    model.place(state);
    scene.add(bkFx.group); bkFx.start(n);
    bkRoadSet(true);                          // hạt nhựa + vệt ướt trên vật liệu đường (roadFx.ts; uRoadNear = 1 nếu CONFIG.bike.road.detail)
    riderNeed();
    riderStep(state, 0);
    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
    bkKeys.clear(); touch?.reset(); hornTouch = false;
    drHudShow(n); bkHudShow(); bkSound.start();
    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
    riderEye();
    bkCamPlace(camera, state, camB, n, 0, true); onResize();   // fov / near góc thứ nhất; onResize cập nhật ma trận chiếu và hệ số cỡ điểm
    controls.target.set(state.x, state.y, state.z);
    document.body.classList.add('explore', 'drive', 'bike');
  },
  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'bike' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng máy;
     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
  startWatching(carry = false): void {
    const s = exMulti.session; if (!s) return;
    const n = drEnsureNet();
    net = n;
    if (state !== null) {   // vừa nhường chỗ: cất xe, người lái, hiệu ứng, tiếng của mình
      riderGen++; rider?.setFirstPerson(false);
      model?.group.removeFromParent(); bkFx.stop(); bkSound.stop(); bkHudHide();
    }
    state = null; watching = true; chased = carry;
    bkKeys.clear(); touch?.reset(); hornTouch = false;
    bkRoadSet(false);                         // hạt nhựa + vệt ướt chỉ khi tự lái
    exDrivers.setSelf(-1);
    driveView.far = CONFIG.drive.tunnelFar;
    drHudShow(n);
    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
    camW.yaw = 0; camW.pitch = 0; camW.idle = 0;
    document.body.classList.add('explore', 'drive', 'bike', 'ex-watching');
    exMulti.onChange = bkOnMultiChange;
    exWatchShow(s);
  },
  update(dt: number): void {
    if (watching) { watchStep(dt); return; }
    if (!active()) return;
    bkInputFromKeys(bkKeys, _inp);
    bkTouchMerge(_inp, _dr, readTouch);   // gộp cảm ứng, không xóa phím (máy lai)
    bkSound.horn(bkKeys.has('KeyH') || hornTouch);
    const s = state!, tun = bkInTunnel(net!, s) && bkCovered(s), wd = weatherU.uWindDir.value;
    _inp.grip = bkGrip(weatherU.uWet.value, tun);                                       // mặt ướt (trễ theo mưa); đoạn hầm kín luôn khô
    _inp.steer += bkGustSteer(s.v, weatherU.uGust.value, wd[0], wd[1], s.yaw);        // gió giật đẩy nhẹ độ nghiêng (≤ fx.gust.steer)
    advance(dt, _inp);
  },
  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
  afterRender(): void { /* chưa có việc */ },
  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
  stop(): void {
    if (state === null && !watching) return;
    state = null; bkKeys.clear(); touch?.reset(); hornTouch = false; riderGen++;
    document.getElementById('bkHorn')?.classList.remove('on');   // thoát khi đang giữ 📢: tắt sáng nút ngay, không chờ ngón nhả
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent(); exDrivers.bikes.removeFromParent();   // xe người khác (ô tô, xe máy)
    bkSound.stop();
    bkHudHide();
    rider?.setFirstPerson(false);
    drHudHide();
    model?.group.removeFromParent();
    bkFx.stop();
    bkRoadSet(false);                         // uRoadNear = 0: vật liệu đường về đúng ảnh cũ
    driveView.far = 1;
    drUseBody(DR_CAR_BODY);
    document.body.classList.remove('drive', 'bike');
    if (saved) {
      if (!saved.explore) document.body.classList.remove('explore');
      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
      saved = null;
    }
    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
  placeAt: bkPlaceAt,
  /* Nạp mô hình thật (scooter.glb) và nhân vật người lái sớm, khi chọn thẻ Xe máy */
  preload(): void { void bkModelLoad(); void bkRiderLoad(stChar.get()); }
};

/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
export function setupBike(c: SwingController, onExit: () => void): void {
  ctrl = c; exit = onExit;
  window.addEventListener('keydown', (e) => {
    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (isField(e.target)) return;
    if (!BK_KEYS.has(e.code)) return;
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
    bkKeys.add(e.code);
    if (e.repeat) return;
    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
    if (e.code === 'KeyR') bkRecover(state!, net!);
    else if (e.code === 'KeyQ') bkSignal(state!, 1);
    else if (e.code === 'KeyE') bkSignal(state!, -1);
    else if (e.code === 'KeyV') bike.setView(camB.view === 3 ? 1 : 3);
  });
  window.addEventListener('keyup', (e) => {
    bkKeys.delete(e.code);
    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
  });
  const drop = drBindDrop(window, document, bkKeys);
  const hornOff = () => { hornTouch = false; bkSound.horn(false); if (hornBtn) hornBtn.classList.remove('on'); };
  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); hornOff(); } });
  window.addEventListener('blur', hornOff);
  document.addEventListener('visibilitychange', () => { if (document.hidden) hornOff(); });
  /* HUD riêng: xi nhan, góc nhìn, về làn bấm một lần (click: chuột, chạm, bàn phím); còi giữ (con trỏ riêng, nhả / hủy / mất capture là thôi) */
  const d = (id: string) => document.getElementById(id);
  const hornBtn = d('bkHorn');
  bkHudBind({ sigL: d('bkSigL'), sigR: d('bkSigR'), stuck: d('bkStuck'), reset: d('bkReset') });
  const onClick = (id: string, f: () => void) => d(id)?.addEventListener('click', () => { if (active()) { exMulti.activity(); f(); } });

