/* Nạp giả: xe chờ tới khi gọi bike.done, nhân vật theo ch chờ tới khi gọi chars[ch].done; asked ghi các ch đã xin */
function loaders(): { bike: ReturnType<typeof defer<THREE.Object3D>>; chars: Map<number, ReturnType<typeof defer<StRigSource | null>>>; asked: number[] } {
