  assert.ok(g.getObjectByName('bike-temp'), 'hình tạm (xe + người khối)');
  assert.ok(Math.abs(g.position.y - 2.6) < 1e-6);
  exDrivers.clear(); bkModelSetLoader(null); exDrivers.__setRiderLoader(null);
});

test('veh 1, ch 1: nạp xong ⇒ xe thật + người lái nhân vật 1 ở đúng chỗ (không về gốc, không khung trống); nạp lỗi ⇒ giữ hình tạm', async () => {
