  assert.ok(pa.distanceTo(ph) < 0.2, 'tay trái gần tay nắm: ' + pa.distanceTo(ph).toFixed(3));
  exDrivers.sync([{ slot: 3, name: 'Khac', veh: 1, ch: 1 }], -1);
  assert.equal(bikeNodes().length, 1); assert.equal(g.parent, null, 'đổi chủ: hình cũ gỡ');
