// Xem tay: hai trang xe máy (A nam ch 0, B nữ ch 1) qua wrangler dev cục bộ 8799 + vite 5199; chụp trang A nhìn xe B gần, góc thứ ba.
import { launch, openApp, frames } from 'file:///D:/2026%20-%20Tuan/danang-vite-xe-may/tests/lib.mjs';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const OUT = 'D:/2026 - Tuan/danang-vite-xe-may/tests/screens/';
const URL = 'http://127.0.0.1:5199/?chooser&multi=' + encodeURIComponent('ws://127.0.0.1:8799/sky') + '&idleMs=600000';
const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);
const browser = await launch();
try {
  const join = async (name, ch) => {
    const X = await openApp(browser, URL, { width: 800, height: 450 });
    X.page.setDefaultTimeout(300000);
    X.page.on('console', (m) => { if (/warn|error/.test(m.type())) console.log(`[${name} ${m.type()}]`, m.text().slice(0, 200)); });
    log(name, 'đã mở');
    await X.page.waitForSelector('#chooser', { state: 'visible', timeout: 300000 });
    await X.page.click('#chooser [data-pick="bike"]');
    await X.page.waitForFunction(() => /\d/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 120000 }).catch(() => {});
    await X.page.click(`#stCharPick button[data-ch="${ch}"]`);
    await X.page.fill('#exMpNameIn', name);
    await X.page.click('#exMpFly');
    await X.page.waitForFunction(() => window.__app.bike.active() && window.__app.multi.session && window.__app.multi.session.phase === 'flying', null, { timeout: 180000, polling: 500 });
    log(name, 'đang lái, slot', await X.page.evaluate(() => window.__app.multi.session.mySlot));
    return X;
  };
  const A = await join('XeA', 0);
  const B = await join('XeB', 1);
  /* cả hai đứng yên (không phím); B đặt ngay trước A 6 m, hơi lệch */
  for (const X of [A, B]) await X.page.evaluate(() => { const K = window.__app.bike, inp = { gas: 0, brake: 1, steer: 0, hard: false, grip: 1 }, step = K.step.bind(K); K.update = (dt) => { if (K.state) step(dt, inp); }; });
  const a = await A.page.evaluate(() => { const s = window.__app.bike.state; return { x: s.x, z: s.z, yaw: s.yaw, y: s.y }; });
  log('A ở', a);
  await B.page.evaluate((a) => { const fx = Math.cos(a.yaw), fz = -Math.sin(a.yaw); window.__app.bike.placeAt(a.x + fx * 6 + fz * 1.2, a.z + fz * 6 - fx * 1.2, a.yaw + 2.6); }, a);
  log('chờ A thấy xe B là xe thật');
  await A.page.waitForFunction(() => { const D = window.__app.multi.drivers; return [0, 1, 2, 3, 4].some((i) => { const d = D.debug(i); return d && d.real; }); }, null, { timeout: 400000, polling: 2000 }).catch(() => log('hết giờ chờ xe thật'));
  await frames(A.page, 3);
  const info = await A.page.evaluate(() => {
    const W = window.__app, D = W.multi.drivers, g = W.scene.getObjectByName('drive-bikes');
    const out = { dbg: [], vis: 0, meshes: 0, withB: NaN, without: NaN };
    for (let i = 0; i < 5; i++) { const d = D.debug(i); if (d) out.dbg.push({ slot: i, ...d, st: D.slotState(i) }); }
    if (g && g.parent) {
      const v = g.children.filter((o) => o.visible); out.vis = v.length;
      if (v[0]) v[0].traverse((o) => { if (o.isMesh && o.visible) out.meshes++; });
      const { renderer, scene, camera } = W, r = () => { renderer.info.reset(); renderer.render(scene, camera); return renderer.info.render.calls; };
      r(); out.withB = r(); g.visible = false; out.without = r(); g.visible = true;
    }
    return out;
  });
  log('A thấy', JSON.stringify(info));
  /* góc thứ ba, camera đã ở sau xe A: chụp */
  await A.page.evaluate(() => window.__app.bike.setView(3));
  await sleep(3000); await frames(A.page, 6);
  await A.page.screenshot({ path: OUT + 'remote-bike-A-sees-B.png' });
  /* nhìn gần xe B: đặt camera ngay cạnh xe B, nhìn vào nó (một khung, rồi trả lại) */
  const st = info.dbg.find((d) => d.st)?.st;
  if (st) {
    await A.page.evaluate((st) => {
      const W = window.__app, K = W.bike; K.update = () => {};
      const c = W.camera; c.position.set(st.x + 2.6 * Math.cos(st.yaw) + 1.6 * Math.sin(st.yaw), st.y + 1.6, st.z - 2.6 * Math.sin(st.yaw) + 1.6 * Math.cos(st.yaw)); c.lookAt(st.x, st.y + 0.9, st.z);
      c.fov = 50; c.near = 0.1; c.updateProjectionMatrix();
    }, st);
    await frames(A.page, 4);
    await A.page.screenshot({ path: OUT + 'remote-bike-close.png' });
  }
  const b = await B.page.evaluate(() => { const D = window.__app.multi.drivers, o = []; for (let i = 0; i < 5; i++) { const d = D.debug(i); if (d) o.push({ slot: i, ...d }); } return o; });
  log('B thấy', JSON.stringify(b));
  log('xong');
} finally { await browser.close(); }

